/**
 * Our PCSO draw statistics for articles. pcso-stats.json is generated by
 * backend/scripts/export_article_stats.py from backend/data/*.xlsx.
 * Formatters use a fixed locale and UTC so prerendered HTML matches hydration.
 */
import data from './pcso-stats.json';

export const GAME_KEYS = data.games.map((g) => g.key);

/** One game's stats by key: '6/42', '6/45', '6/49', '6/55' or '6/58'. */
export const gameStats = (key) => data.games.find((g) => g.key === key);

export const allGames = () => data.games;

/** "Dec 26, 2025" */
export const formatDate = (iso) =>
  new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });

/** 13983816 -> "13,983,816" */
export const formatNumber = (n) => Math.round(n).toLocaleString('en-US');

/** 0.333 -> "33.3%" */
export const formatPercent = (share, digits = 1) => `${(share * 100).toFixed(digits)}%`;

/** 1180622508 -> "₱1.18 billion", 640654817.6 -> "₱640.7 million" */
export const formatPeso = (n) =>
  n >= 1e9 ? `₱${(n / 1e9).toFixed(2)} billion` : `₱${(n / 1e6).toFixed(1)} million`;

/** "Jan 3, 2015 to Dec 25, 2025" for one game, or the widest range across all games. */
export const dataRange = (key) => {
  const games = key ? [gameStats(key)] : data.games;
  const first = games.map((g) => g.first).sort()[0];
  const last = games.map((g) => g.last).sort().at(-1);
  return `${formatDate(first)} to ${formatDate(last)}`;
};
